package dev.codingtransfer.core;

import java.io.IOException;
import java.nio.file.*;
import java.util.*;
import static dev.codingtransfer.core.Model.*;

final class BundleSessionExitTest {
    private interface Checked { void run() throws Exception; }
    private static void rejected(Checked action)throws Exception { try{action.run();}catch(IOException expected){return;}throw new AssertionError("expected rejection"); }
    static void run(Path temp)throws Exception {
        Path vm=temp.resolve("exit-vm");TestSupport.initRepository(vm);Files.writeString(vm.resolve("a.txt"),"one");TestSupport.git(vm,"add","a.txt");TestSupport.git(vm,"commit","-qm","initial");
        Config cfg=new Config(Role.VM,List.of(new Config.Mapping("demo","project",vm.toString())),List.of(),4,"git");BundleSync sync=new BundleSync(vm,cfg);
        Payload old=sync.generate("demo",false).payload();String session=UUID.randomUUID().toString();var parts=ClipboardTransport.split(old,4);var sessions=new TransferSessionStore(vm);
        new ProjectOutgoingStore(vm).save(session,old,parts);sessions.saveContext(new TransferSessionStore.Context(session,"demo",old.git().snapshot(),ReliableTransferEngine.Kind.PROJECT,ReliableTransferEngine.Direction.VM_TO_HOST,parts.size()));sessions.saveFrame(session,"retained-frame");sessions.saveState(session,new byte[]{1,2,3});sync.markAutomaticTransferStarted("demo",session,old.git().snapshot(),parts.size());
        sync.endAutomaticTransfer("demo",session);
        TestSupport.check(!sync.hasUnacknowledgedPending("demo")&&sessions.currentContext()==null,"ending frees active occupancy");
        TestSupport.check(!Files.exists(vm.resolve(".vmsync/bundle-state/acknowledged/demo.gz"))&&sessions.readFrame(session).equals("retained-frame")&&Arrays.equals(sessions.readState(session),new byte[]{1,2,3})&&new ProjectOutgoingStore(vm).load(session).git().snapshot().equals(old.git().snapshot()),"ending preserves progress source and baseline");
        Payload receipt=new Payload(Type.ACK,"demo",old.head(),old.policy(),List.of(),new GitData(old.git().snapshot(),old.git().parent(),"",new TreeMap<>(),new byte[0]));
        rejected(()->sync.acceptReceipt("demo",receipt));Payload newer=sync.generate("demo",false).payload();rejected(()->sync.acceptReceipt("demo",receipt));
        String foreignSession=UUID.randomUUID().toString();sessions.saveContext(new TransferSessionStore.Context(foreignSession,"demo","other",ReliableTransferEngine.Kind.FILE,ReliableTransferEngine.Direction.VM_TO_HOST,1));rejected(()->sync.restoreEndedTransfer("demo"));TestSupport.check(sessions.currentContext().session().equals(foreignSession),"recovery preserves another active transfer");sessions.clearContext(foreignSession);
        new PendingBundleTransferStore(vm).mark(new PendingBundleTransferStore.Transfer("demo",foreignSession,"other",1));byte[] draft=Files.readAllBytes(vm.resolve(".vmsync/bundle-state/pending/demo.gz"));rejected(()->sync.restoreEndedTransfer("demo"));TestSupport.check(Arrays.equals(draft,Files.readAllBytes(vm.resolve(".vmsync/bundle-state/pending/demo.gz")))&&new PendingBundleTransferStore(vm).read().session().equals(foreignSession),"recovery preserves another active Bundle");new PendingBundleTransferStore(vm).clear("demo",foreignSession);
        BundleSync restart=new BundleSync(vm,cfg);TestSupport.check(restart.hasEndedTransfer("demo"),"ended recovery survives restart");Path pending=vm.resolve(".vmsync/bundle-state/pending/demo.gz"),savedPending=vm.resolve(".vmsync/bundle-state/pending/draft.gz");Files.move(pending,savedPending);Files.createDirectory(pending);rejected(()->restart.restoreEndedTransfer("demo"));TestSupport.check(restart.needsEndedRestore("demo")&&sessions.currentContext().session().equals(session),"failed restore retains an explicit retry path");Files.delete(pending);Files.move(savedPending,pending);restart.repairEndedRestore("demo");TestSupport.check(sessions.currentContext().session().equals(session)&&sync.hasUnacknowledgedPending("demo"),"explicit recovery restores original target and occupancy");rejected(()->sync.generate("demo",false));sync.acceptReceipt("demo",receipt);
        // Ending another transfer must not let a later baseline be replaced by its old receipt.
        sessions.clearContext(session);Payload next=sync.generate("demo",true).payload();String nextSession=UUID.randomUUID().toString();var nextParts=ClipboardTransport.split(next,4);new ProjectOutgoingStore(vm).save(nextSession,next,nextParts);sessions.saveContext(new TransferSessionStore.Context(nextSession,"demo",next.git().snapshot(),ReliableTransferEngine.Kind.PROJECT,ReliableTransferEngine.Direction.VM_TO_HOST,nextParts.size()));sync.markAutomaticTransferStarted("demo",nextSession,next.git().snapshot(),nextParts.size());sync.endAutomaticTransfer("demo",nextSession);
        Payload replacement=sync.generate("demo",false).payload();Payload replacementAck=new Payload(Type.ACK,"demo",replacement.head(),replacement.policy(),List.of(),new GitData(replacement.git().snapshot(),"-","",new TreeMap<>(),new byte[0]));sync.acceptReceipt("demo",replacementAck);byte[] baseline=Files.readAllBytes(vm.resolve(".vmsync/bundle-state/acknowledged/demo.gz"));rejected(()->sync.restoreEndedTransfer("demo"));TestSupport.check(Arrays.equals(baseline,Files.readAllBytes(vm.resolve(".vmsync/bundle-state/acknowledged/demo.gz")))&&sessions.currentContext()==null,"stale recovery cannot rewind baseline");
        Payload failure=sync.generate("demo",true).payload();String failureSession=UUID.randomUUID().toString();var failureParts=ClipboardTransport.split(failure,4);new ProjectOutgoingStore(vm).save(failureSession,failure,failureParts);sessions.saveContext(new TransferSessionStore.Context(failureSession,"demo",failure.git().snapshot(),ReliableTransferEngine.Kind.PROJECT,ReliableTransferEngine.Direction.VM_TO_HOST,failureParts.size()));sync.markAutomaticTransferStarted("demo",failureSession,failure.git().snapshot(),failureParts.size());
        Path bad=vm.resolve(".vmsync/bundle-state/ended").resolve(failureSession);Files.writeString(bad,"block archive creation");rejected(()->sync.endAutomaticTransfer("demo",failureSession));TestSupport.check(sessions.currentContext().session().equals(failureSession)&&new PendingBundleTransferStore(vm).read().session().equals(failureSession),"archive failure retains active recovery state");
        Files.delete(bad);Files.createDirectories(bad.resolve("current.context"));rejected(()->sync.endAutomaticTransfer("demo",failureSession));TestSupport.check(sessions.currentContext().session().equals(failureSession)&&new PendingBundleTransferStore(vm).read().session().equals(failureSession)&&new ProjectOutgoingStore(vm).load(failureSession).git().snapshot().equals(failure.git().snapshot()),"partial archive failure preserves source and active pointers");Files.delete(bad.resolve("current.context"));sync.endAutomaticTransfer("demo",failureSession);TestSupport.check(sessions.currentContext()==null&&new PendingBundleTransferStore(vm).read()==null,"failed ending can be retried");
        new PendingBundleTransferStore(vm).mark(new PendingBundleTransferStore.Transfer("demo",failureSession,failure.git().snapshot(),failureParts.size()));TestSupport.check(sync.needsEndedRestore("demo"),"incomplete end is repairable without context");sync.repairEndedRestore("demo");Payload failureAck=new Payload(Type.ACK,"demo",failure.head(),failure.policy(),List.of(),new GitData(failure.git().snapshot(),failure.git().parent(),"",new TreeMap<>(),new byte[0]));sync.acceptReceipt("demo",failureAck);TestSupport.check(new PendingBundleTransferStore(vm).read()==null&&Codec.decode(Files.readAllBytes(vm.resolve(".vmsync/bundle-state/acknowledged/demo.gz"))).git().snapshot().equals(failure.git().snapshot()),"first recovery after interrupted end accepts original receipt");
        System.out.println("PASS Bundle session exit/recovery");
    }
}
